using System;using System.IO;using System.Text.Json;using System.Collections.Generic;using System.Security.Cryptography;using Lin.Helper.Core.Tile;
class Program {
 static object Pin(string path){var b=File.ReadAllBytes(path);return new{path,bytes=b.Length,sha256=Convert.ToHexString(SHA256.HashData(b))};}
 static void Main(string[] args){var m=JsonDocument.Parse(File.ReadAllBytes(args[0]));var root=m.RootElement.GetProperty("output_root").GetString();var rows=new List<object>();foreach(var c in m.RootElement.GetProperty("cases").EnumerateArray()){var p=c.GetProperty("block").GetProperty("path").GetString();var raw=File.ReadAllBytes(p);if(Convert.ToHexString(SHA256.HashData(raw))!=c.GetProperty("block").GetProperty("sha256").GetString())throw new Exception("pin drift");var bgra=new byte[24*24*4];L1Til.RenderBlockToBgra(raw,0,0,bgra,24,24,0,0,0,true,true);var rgba=new byte[bgra.Length];for(int i=0;i<bgra.Length;i+=4){rgba[i]=bgra[i+2];rgba[i+1]=bgra[i+1];rgba[i+2]=bgra[i];rgba[i+3]=bgra[i+3];}var name=c.GetProperty("name").GetString();var output=Path.Combine(root,name+".rgba");File.WriteAllBytes(output,rgba);rows.Add(new{name,block=Pin(p),rgba=Pin(output),actual=c.GetProperty("actual").GetBoolean()});}File.WriteAllText(args[1],JsonSerializer.Serialize(new{state="R485_UNMODIFIED_WHOLE_CSHARP_TILE_SOURCE_12_REFERENCE_RGBA_OUTPUTS",cases=rows},new JsonSerializerOptions{WriteIndented=true}));Console.WriteLine("R485 unchanged C# source:12 RGBA references produced");}
}
